<template><Layout><div class="breadcrumb"><Link :href="route('dashboard')">Overview</Link><span>›</span>Orders</div><div class="page-header"><div><div class="eyebrow">MARKETPLACE OPERATIONS</div><h1>Orders</h1><p>Monitor every transaction and follow its current status.</p></div></div><section class="order-tabs"><button v-for="tab in tabs" :key="tab.value" :class="{active:status===tab.value}" @click="status=tab.value">{{ tab.label }} <span>{{ count(tab.value) }}</span></button></section><section class="listing-panel"><div class="listing-toolbar"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search order, user or product…"/></div><span>{{ filtered.length }} orders</span></div><div v-if="filtered.length" class="orders-list"><div class="order-row order-head"><span>Order</span><span>Customer</span><span>Product</span><span>Total</span><span>Status</span><span></span></div><Link v-for="order in filtered" :key="order.id" :href="route('orders.show',order.id)" class="order-row"><div><strong>#{{ order.code }}</strong><small>{{ formatDate(order.created_at) }}</small></div><div class="user-cell"><span class="tiny-avatar"><img v-if="order.buyer?.image" :src="order.buyer.image"/><b v-else>{{ initial(order.buyer?.name) }}</b></span>{{ order.buyer?.name||'Deleted user' }}</div><span>{{ order.product?.name||'Deleted product' }}</span><strong>{{ money(order.total_price) }}</strong><span class="status-pill" :class="statusClass(order.status)">{{ readable(order.status) }}</span><b>›</b></Link></div><div v-else class="empty-state"><div>⌕</div><strong>No orders found</strong><p>Try a different search or status filter.</p></div></section></Layout></template>
<script setup>import{ref,computed}from'vue';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({orders:{type:Array,default:()=>[]}}),query=ref(''),status=ref('all');const tabs=[{label:'All',value:'all'},{label:'Pending',value:'pending'},{label:'In progress',value:'progress'},{label:'Completed',value:'completed'},{label:'Rejected',value:'rejected'}];const group=s=>s?.includes('reject')?'rejected':['received','delivered'].includes(s)?'completed':['order-pending','on-hold'].includes(s)?'pending':'progress';const count=v=>v==='all'?props.orders.length:props.orders.filter(o=>group(o.status)===v).length;const filtered=computed(()=>{const q=query.value.toLowerCase();return props.orders.filter(o=>(status.value==='all'||group(o.status)===status.value)&&[o.code,o.buyer?.name,o.product?.name].some(x=>x?.toLowerCase().includes(q)))});const readable=s=>s.replaceAll('-',' ').replace(/\b\w/g,l=>l.toUpperCase()),statusClass=s=>group(s)==='rejected'?'status-red':group(s)==='completed'?'status-green':'status-amber';const money=v=>new Intl.NumberFormat('en-US').format(v)+' Ks',formatDate=d=>new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(d)),initial=n=>(n||'?').charAt(0).toUpperCase();</script>
